fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Given the length invariants from the problem statement,
    // a and b are non-empty and have the same length.
    // We can iterate over paired elements and XOR them.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x ^ y)
        .collect()
}